void far EndMigrate(int x, int y)
{
    int half;
    int from;
    int src;
    int dst;
    int tx;
    int ty;

    from = MigrateX;
    if (from < 0)
        return;
    ty = (y - 66) / 10;
    tx = (y + x - 238) / 28;
    if (tx < 0 || ty < 0 || tx > 11 || ty > 15)
        return;
    src = from * 16 + MigrateY;
    half = Dx8[src + 0xa4] >> 1;
    Dx8[src + 0xa4] -= half;
    dst = tx * 16 + ty;
    if (Dx8[dst + 0xa4] + half < 0xfb)
        Dx8[dst + 0xa4] += half;
    else
        Dx8[dst + 0xa4] = 0xfa;
}
